private void sendInviteRequest(CallParticipantSipImpl sipParticipant, String sdpOffer) throws OperationFailedException {
  Dialog dialog = sipParticipant.getDialog();
  try {
    Request invite = createRequest(dialog, Request.INVITE);
    invite.setContent(sdpOffer, protocolProvider.getHeaderFactory().createContentTypeHeader("application", "sdp"));
  } catch (ParseException ex) {
    throwOperationFailedException("Failed to parse SDP offer for the new invite.", OperationFailedException.INTERNAL_ERROR, ex);
  } catch (NullPointerException ex) {
    throwOperationFailedException("Failed to create invite request due to null value.", OperationFailedException.INTERNAL_ERROR, ex);
  }
  sendRequest(sipParticipant.getJainSipProvider(), invite, dialog);
}
